    expect(exactMatch.score).toBe(1);
    expect(exactMatch.min).toBe(1);
  });

  it('marks thresholds as failed when score is below minimum', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {
        exact_match: 1.1
      }
    });

    expect(report.passed).toBe(false);
    const threshold = report.thresholds[0];
    expect(threshold.passed).toBe(false);
    expect(threshold.score).toBe(1);
    expect(threshold.min).toBe(1.1);
  });

  it('marks thresholds as failed when metric has no score', () => {
    const evaluations = runEvaluations({
      outputs: [],
      references: []
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {
        exact_match: 0.5
      }
    });

    expect(report.passed).toBe(false);
    const threshold = report.thresholds[0];
    expect(threshold.passed).toBe(false);
    expect(threshold.score).toBe(null);
  });

