477	function parseThreshold(
478	  thresholdStr: string,
479	  validMetricIds: string[]
480	): { metric: string; min: number } {
481	  const match = thresholdStr.match(/^([a-z_]+)=(.+)$/);
482	  if (!match) {
483	    throw new Error(`Malformed threshold: "${thresholdStr}". Expected format: <metric>=<min>`);
484	  }
485	
486	  const [, metric, minStr] = match;
487	  const min = Number.parseFloat(minStr);
488	
489	  if (!Number.isFinite(min) || min < 0 || min > 1) {
490	    throw new Error(`Invalid threshold minimum: "${minStr}". Must be a number between 0 and 1.`);
491	  }
492	
493	  if (!validMetricIds.includes(metric)) {
494	    throw new Error(
495	      `Unknown metric: "${metric}". Valid metrics are: ${validMetricIds.join(', ')}`
496	    );
497	  }
498	
499	  return { metric, min };
500	}
