502	function runEvalCommand(options: EvalOptions) {
503	  assertFileExists(options.outputs);
504	  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
505	    outputsPath: options.outputs,
506	    referencesPath: options.references
507	  });
508	  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
509	    outputs: dataset.outputs,
510	    references: dataset.references
511	  });
512	
513	  const thresholds: Record<string, number> = {};
514	  if (options.threshold && options.threshold.length > 0) {
515	    const validMetricIds = evaluations.map((metric: { id: string }) => metric.id);
516	    for (const thresholdStr of options.threshold) {
517	      try {
518	        const { metric, min } = parseThreshold(thresholdStr, validMetricIds);
519	        thresholds[metric] = min;
520	      } catch (error) {
521	        log.error((error as Error).message);
522	        process.exit(2);
523	      }
524	    }
525	  }
526	
527	  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
528	    evaluations,
529	    outputsPath: dataset.outputsPath,
530	    referencesPath: dataset.referencesPath,
531	    thresholds
532	  });
533	  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
534	    report,
535	    format: options.format ?? 'json',
536	    reportPath: options.report
537	  });
538	  log.success('Evaluation report generated.', { path: resolvedPath });
539	
540	  if (Object.keys(thresholds).length > 0 && !report.passed) {
541	    process.exit(1);
542	  }
543	}
